import { Engine } from '@lupis/core';

// Inisialisasi engine pada resolusi 800x600
const game = new Engine({
  canvasId: 'game-canvas',
  width: 800,
  height: 600,
  backgroundColor: '#1a1a24'
});

game.start();

import { Entity, RectComponent } from '@lupis/core';

// Membuat entity baru
const player = new Entity('Player1');

// Mengatur posisi ke tengah layar
player.position.set(400, 300);

// Menambahkan komponen visual (Kotak merah ukuran 50x50)
player.addComponent(new RectComponent(50, 50, '#ff0055'));

// Masukkan entity ke dalam scene aktif
game.scene.add(player);

game.onUpdate((deltaTime) => {
  // Gerakkan player ke kanan sebesar 100 pixel per detik
  player.position.x += 100 * deltaTime;

  // Reset posisi jika keluar batas layar
  if (player.position.x > 850) {
    player.position.x = -50;
  }
});
